for t in targets:
    prev = None
    for addr, name in syms:
        if addr > t:
            break
        prev = (addr, name)
    if prev:
        print(f'0x{t:x}: {prev[1]}+0x{t-prev[0]:x} (base 0x{prev[0]:x})')
    else:
        print(f'0x{t:x}: ???')
"", "description": "Find functions with python"}

